<?php
declare(strict_types=1);
session_start();
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
if (strtolower((string)($_SESSION['user_role'] ?? '')) !== 'student') { http_response_code(403); exit('This page is for student accounts only.'); }
function nh($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
try {
    $pdo = new PDO('mysql:host=127.0.0.1;port=3306;dbname=kanji_master;charset=utf8mb4', 'root', 'root', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
    $pdo->exec("CREATE TABLE IF NOT EXISTS student_notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, notification_type VARCHAR(40) NOT NULL, title VARCHAR(180) NOT NULL, message VARCHAR(500) NOT NULL, target_url VARCHAR(500) NOT NULL, is_read TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_student_notifications_user (user_id, is_read, created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $uid = (int)$_SESSION['user_id'];
    if (isset($_GET['open']) && ctype_digit((string)$_GET['open'])) {
        $stmt = $pdo->prepare('SELECT target_url FROM student_notifications WHERE id=? AND user_id=?');
        $stmt->execute([(int)$_GET['open'], $uid]); $target = $stmt->fetchColumn();
        if ($target) {
            $mark = $pdo->prepare('UPDATE student_notifications SET is_read=1 WHERE id=? AND user_id=?'); $mark->execute([(int)$_GET['open'], $uid]);
            // Only allow redirects to local PHP pages, never external URLs.
            if (is_string($target) && preg_match('/^[a-zA-Z0-9_-]+\.php(?:\?[a-zA-Z0-9_=&%-]*)?$/', $target)) { header('Location: ' . $target); exit; }
        }
    }
    if (isset($_GET['read_all']) && $_GET['read_all'] === '1') { $stmt=$pdo->prepare('UPDATE student_notifications SET is_read=1 WHERE user_id=?'); $stmt->execute([$uid]); header('Location: notifications.php'); exit; }
    $stmt=$pdo->prepare('SELECT id,notification_type,title,message,target_url,is_read,created_at FROM student_notifications WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT 100'); $stmt->execute([$uid]); $notifications=$stmt->fetchAll();
} catch (Throwable $e) { error_log('Kanji Master notifications page: '.$e->getMessage()); http_response_code(500); exit('Could not load notifications. Check MAMP MySQL.'); }
$unread=0; foreach($notifications as $n) if (!(int)$n['is_read']) $unread++;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications | Kanji Master</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#f8fafc;font:15px/1.55 Arial,sans-serif}header{padding:18px 4%;background:#111827;border-bottom:1px solid #263247;display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;align-items:center}.brand{font-weight:800}.brand span,a{color:#c7d2fe}a{text-decoration:none}a:hover{text-decoration:underline}main{width:min(850px,92%);margin:30px auto 60px}h1{margin:5px 0 4px;font-size:32px}.sub{color:#cbd5e1}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:18px 0}.button{display:inline-block;padding:8px 11px;border:1px solid #475569;border-radius:9px;color:#fff;background:#1f2937}.notice{background:#151d31;border:1px solid #334155;border-radius:13px;margin:10px 0;overflow:hidden}.notice.unread{border-color:#818cf8;background:#18213a}.notice a{display:block;padding:16px;color:inherit}.row{display:flex;gap:12px;align-items:flex-start}.symbol{font-size:22px;line-height:1.2}.title{font-weight:800;color:#e0e7ff}.message{color:#cbd5e1;margin-top:4px}.meta{font-size:12px;color:#94a3b8;margin-top:8px}.unread-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#818cf8;margin-left:6px}.empty{padding:28px;text-align:center;border:1px dashed #475569;border-radius:13px;color:#cbd5e1}@media(max-width:600px){h1{font-size:27px}}</style></head><body><header><div class="brand">日本語 <span>Kanji Master</span></div><nav><a href="dashboard.php">← Dashboard</a></nav></header><main><div class="sub">STUDENT CENTER</div><h1>Notifications 🔔</h1><div class="sub">Assignments and feedback from your teacher.</div><div class="toolbar"><span><?=count($notifications)?> messages · <?=$unread?> unread</span><?php if($unread): ?><a class="button" href="notifications.php?read_all=1">Mark all as read</a><?php endif; ?></div><?php if(!$notifications): ?><div class="empty">You're all caught up. New assignments and teacher feedback will appear here.</div><?php else: foreach($notifications as $n): ?><article class="notice <?=!(int)$n['is_read']?'unread':''?>"><a href="notifications.php?open=<?=(int)$n['id']?>"><div class="row"><div class="symbol"><?=($n['notification_type']==='assignment'?'📚':'💬')?></div><div><div class="title"><?=nh($n['title'])?><?php if(!(int)$n['is_read']): ?><span class="unread-dot" title="Unread"></span><?php endif; ?></div><div class="message"><?=nh($n['message'])?></div><div class="meta"><?=nh(date('Y-m-d H:i',strtotime($n['created_at'])))?> · Click to open</div></div></div></a></article><?php endforeach; endif; ?></main></body></html>